using namespace std;
void solve(istream& in, ostream& out) {
    int a, b, n;
    in >> a >> b >> n;
    const int inf = 1000000000;
    vector<int> from_a(10001, inf), to_b(10001, inf);
    int answer = a == b ? 0 : inf;
    for (int route = 0; route < n; ++route) {
        int cost, length; in >> cost >> length;
        vector<int> cities(length);
        int ia = -1, ib = -1;
        for (int i = 0; i < length; ++i) {
            in >> cities[i];
            if (cities[i] == a) ia = i;
            if (cities[i] == b) ib = i;
        }
        if (ia != -1 && ib > ia) answer = min(answer, cost);
        if (ia != -1)
            for (int i = ia + 1; i < length; ++i)
                from_a[cities[i]] = min(from_a[cities[i]], cost);
        if (ib != -1)
            for (int i = 0; i < ib; ++i)
                to_b[cities[i]] = min(to_b[cities[i]], cost);
    }
    for (int city = 1; city <= 10000; ++city)
        if (from_a[city] != inf && to_b[city] != inf)
            answer = min(answer, from_a[city] + to_b[city]);
    out << (answer == inf ? -1 : answer) << '\n';
