#include <fstream>
#include <istream>
#include <ostream>
#include <string>
using namespace std;
long long value(const string& digits, int base) {
    long long result = 0;
    for (char digit : digits) result = result * base + digit - '0';
    return result;
}
void solve(istream& in, ostream& out) {
    long long cases; in >> cases;
    while (cases--) {
        string first, second; in >> first >> second;
        int x = 10, y = 10;
        while (x <= 15000 && y <= 15000) {
            long long a = value(first, x), b = value(second, y);
            if (a == b) {
                out << x << ' ' << y << '\n';
                break;
            }
            if (a < b) ++x;
            else ++y;
        }
    }
}
int main() {
    ifstream in("whatbase.in");
    ofstream out("whatbase.out");
    solve(in, out);
    return 0;
}
