#include <fstream>
#include <istream>
#include <ostream>
#include <vector>
using namespace std;
struct Edge { int to, bessie, elsie; };
void solve(istream& in, ostream& out) {
    int n, m; in >> n >> m;
    vector<vector<Edge>> edges(n);
    for (int i = 0; i < m; ++i) {
        int a, b, c, d; in >> a >> b >> c >> d;
        edges[a - 1].push_back({b - 1, c, d});
    }
    int limit = (n - 1) * 1000;
    vector<vector<char>> first(n, vector<char>(limit + 1, false));
    vector<vector<char>> second(n, vector<char>(limit + 1, false));
    first[0][0] = second[0][0] = true;
    for (int field = 0; field < n; ++field) {
        for (const Edge& edge : edges[field]) {
            for (int time = 0; time <= limit; ++time) {
                if (first[field][time] && time + edge.bessie <= limit)
                    first[edge.to][time + edge.bessie] = true;
                if (second[field][time] && time + edge.elsie <= limit)
                    second[edge.to][time + edge.elsie] = true;
            }
        }
    }
    for (int time = 0; time <= limit; ++time) {
        if (first[n - 1][time] && second[n - 1][time]) {
            out << time << '\n';
            return;
        }
    }
    out << "IMPOSSIBLE\n";
}
int main() {
    ifstream in("meeting.in");
    ofstream out("meeting.out");
    solve(in, out);
    return 0;
}
